#include <stdio.h>

int main(void) {
    int n, i;
    double balance = 0.0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        char type;
        double amount;
        scanf(" %c %lf", &type, &amount);
        switch (type) {
            case 'D': case 'd':
                balance += amount;
                break;
            case 'W': case 'w':
                if (amount <= balance) {
                    balance -= amount;
                }
                break;
            case 'B': case 'b':
                /* balance check, no change */
                break;
            default:
                break;
        }
    }
    printf("%.2f\n", balance);
    return 0;
}

