#include <stdio.h>

typedef struct {
    int id;
    int qty;
    double price;
} InvItem;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    InvItem arr[1000];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d %lf", &arr[i].id, &arr[i].qty, &arr[i].price) != 3) {
            return 1;
        }
    }
    FILE *fp = fopen("/tmp/atom_day20_invent.bin", "wb");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    fwrite(arr, sizeof(InvItem), n, fp);
    fclose(fp);
    fp = fopen("/tmp/atom_day20_invent.bin", "rb");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    InvItem rb[1000];
    size_t got = fread(rb, sizeof(InvItem), n, fp);
    fclose(fp);
    double total = 0.0;
    int top_id = -1;
    double top_val = -1.0;
    for (size_t i = 0; i < got; i++) {
        double v = (double)rb[i].qty * rb[i].price;
