#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint32_t a, b;
    while (scanf("%u %u", &a, &b) == 2) {
        if (b == 0) {
            printf("-1\n");
            continue;
        }
        uint32_t quotient = 0;
        uint32_t remainder = 0;
        for (int i = 31; i >= 0; i--) {
            remainder <<= 1;
            remainder |= (a >> i) & 1u;
            if (remainder >= b) {
                remainder -= b;
                quotient |= ((uint32_t)1 << i);
            }
        }
        printf("%u\n", quotient);
    }
    return 0;
}

