int main(void) {
    int n;
    scanf("%d", &n);
    char row[410];
    int mid = n - 1;
    int width = 2 * n - 1;
    for (int i = 0; i < width; i++) {
        int k = 0;
        for (int j = 0; j < width; j++) {
            int di = (i > mid) ? (i - mid) : (mid - i);
            int dj = (j > mid) ? (j - mid) : (mid - j);
            int dist = di + dj;
            if (dist <= mid) {
                row[k++] = (char)('0' + (n - dist));
            } else {
                row[k++] = ' ';
            }
        }
        row[k] = '\0';
        int end = k;
        while (end > 0 && row[end - 1] == ' ') end--;
        row[end] = '\0';
        puts(row);
    }
    return 0;
}

