#include <stdio.h>

static long long memo[51];

static long long fibRec(int n) {
    if (n <= 1) return n;
    if (memo[n] != 0) return memo[n];
    memo[n] = fibRec(n - 1) + fibRec(n - 2);
    return memo[n];
}

int main(void) {
    int n;
    scanf("%d", &n);
    long long rec = fibRec(n);
    long long a = 0, b = 1, c;
    if (n == 0) c = 0;
    else if (n == 1) c = 1;
    else {
        c = 0;
        for (int i = 2; i <= n; i++) {
            c = a + b;
            a = b;
            b = c;
        }
    }
    printf("%lld\n", rec);
    printf("%lld\n", c);
    return 0;
}

