    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (cmp_str(p[i], p[j]) > 0) {
                char *t = p[i];
                p[i] = p[j];
                p[j] = t;
            }
        }
    }
    printf("%s\n%s\n%s\n", p[0], p[1], p[2]);
    return 0;
}

