#include <stdio.h>

int is_prime(int n) {
    if (n < 2) return 0;
    int i;
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int is_armstrong(int n) {
    if (n < 0) return 0;
    int ndigits = 0;
    int temp = n;
    if (temp == 0) ndigits = 1;
    while (temp != 0) {
        ndigits++;
        temp /= 10;
    }
    int sum = 0;
    temp = n;
    while (temp != 0) {
        int digit = temp % 10;
        int p = 1;
        int i;
        for (i = 0; i < ndigits; i++) {
            p *= digit;
        }
        sum += p;
        temp /= 10;
    }
    return sum == n;
}

int is_perfect(int n) {
    if (n < 2) return 0;
    int sum = 1;
    int i;
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            sum += i;
            if (i != n / i) {
                sum += n / i;
            }
        }
    }
    return sum == n;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("Prime: %s\n", is_prime(n) ? "Yes" : "No");
    printf("Armstrong: %s\n", is_armstrong(n) ? "Yes" : "No");
    printf("Perfect: %s\n", is_perfect(n) ? "Yes" : "No");
    return 0;
}

