        nums[n++] = atoi(buf);
    }
    int result;
    if (strcmp(op, "+") == 0) {
        result = 0;
        for (int i = 0; i < n; i++) {
            result += nums[i];
        }
    } else if (strcmp(op, "-") == 0) {
        result = (n > 0) ? nums[0] : 0;
        for (int i = 1; i < n; i++) {
            result -= nums[i];
        }
    } else if (strcmp(op, "*") == 0) {
        result = (n > 0) ? 1 : 0;
        for (int i = 0; i < n; i++) {
            result *= nums[i];
        }
    } else {
        result = 0;
    }
    printf("%d\n", result);
    return 0;
}

