#include <stdio.h>

typedef enum {
    STATE_IDLE,
    STATE_ACTIVE,
    STATE_PAUSED,
    STATE_STOPPED
} State;

typedef enum {
    EVENT_START,
    EVENT_PAUSE,
    EVENT_STOP,
    EVENT_RESUME
} Event;

State transition(State current, Event e) {
    switch (current) {
        case STATE_IDLE:
            if (e == EVENT_START) return STATE_ACTIVE;
            return STATE_IDLE;
        case STATE_ACTIVE:
            if (e == EVENT_PAUSE) return STATE_PAUSED;
            if (e == EVENT_STOP) return STATE_STOPPED;
            return STATE_ACTIVE;
        case STATE_PAUSED:
            if (e == EVENT_RESUME) return STATE_ACTIVE;
            if (e == EVENT_STOP) return STATE_STOPPED;
            return STATE_PAUSED;
        case STATE_STOPPED:
            return STATE_STOPPED;
        default:
            return STATE_IDLE;
    }
}

int main(void) {
    int s, e;
    if (scanf("%d %d", &s, &e) != 2) {
        return 1;
    }
    State next = transition((State)s, (Event)e);
    printf("%d\n", (int)next);
    return 0;
}

