        result = 0;
        for (int i = 0; i < vn; i++) {
            result += values[i];
        }
    } else if (strcmp(cmd, "sub") == 0) {
        result = vn > 0 ? values[0] : 0;
        for (int i = 1; i < vn; i++) {
            result -= values[i];
        }
    } else if (strcmp(cmd, "mul") == 0) {
        result = vn > 0 ? 1 : 0;
        for (int i = 0; i < vn; i++) {
            result *= values[i];
        }
    } else {
        result = 0;
    }
