#include <stdio.h>

static long long sumIter(int n) {
    long long s = 0;
    for (int i = 1; i <= n; i++) s += i;
    return s;
}

static long long sumRec(int n) {
    if (n == 0) return 0;
    return n + sumRec(n - 1);
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%lld\n", sumIter(n));
    printf("%lld\n", sumRec(n));
    return 0;
}

