#include <stdio.h>

typedef enum {
    RED, YELLOW, GREEN
} Light;

Light next_light(Light current) {
    switch (current) {
        case RED: return GREEN;
        case YELLOW: return RED;
        case GREEN: return YELLOW;
        default: return RED;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    Light next = next_light((Light)n);
    printf("%d\n", (int)next);
    return 0;
}

