#include <stdio.h>

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 1;
    }
    int total = n + m;
    int arr[2000];
    for (int i = 0; i < total; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            return 1;
        }
    }
    FILE *fp = fopen("/tmp/atom_day20_ledger.txt", "w");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    for (int i = 0; i < n; i++) {
        fprintf(fp, "%d\n", arr[i]);
    }
    fclose(fp);
    fp = fopen("/tmp/atom_day20_ledger.txt", "a");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    for (int i = n; i < total; i++) {
        fprintf(fp, "%d\n", arr[i]);
    }
    fclose(fp);
    fp = fopen("/tmp/atom_day20_ledger.txt", "r");
    if (fp == NULL) {
        printf("OPEN_FAIL\n");
        return 0;
    }
    int balance = 0;
    int c;
    int sign = 1;
    int in_num = 0;
    int cur = 0;
    while ((c = fgetc(fp)) != EOF) {
        if (c == '-') {
            sign = -1;
        } else if (c >= '0' && c <= '9') {
            cur = cur * 10 + (c - '0');
            in_num = 1;
        } else {
            if (in_num) {
                balance += sign * cur;
                cur = 0;
                sign = 1;
                in_num = 0;
            }
        }
    }
    if (in_num) {
        balance += sign * cur;
    }
    fclose(fp);
    printf("BALANCE %d\n", balance);
    return 0;
}

