#include <errno.h>
int try_op(int op, int t) {
    int target = op % 4;
    if (target == 0) return 0;
    return (t >= target) ? 1 : 0;
}
int main(void) {
    int op;
    if (scanf("%d", &op) != 1) return 1;
    int ok = 0, last = 0;
    for (int t = 1; t <= 3; t++) {
        last = t;
        if (try_op(op, t)) { ok = 1; break; }
    }
    if (ok) printf("OK %d\n", last);
    else { errno = EAGAIN; printf("FAILED %d\n", errno); }
    return 0;
}

