#include <stdio.h>
#include <string.h>
int main(void) {
    char d[20] = "Hello";
    char s[] = " World";
    strcat(d, s);
    printf("%s\n", d);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char *a = "apple";
    char *b = "apply";
    int r = strcmp(a, b);
    printf("%d\n", r < 0 ? -1 : (r > 0 ? 1 : 0));
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char d[5] = "AB";
    char s[] = "CDEF";
    strncat(d, s, 2);
    printf("%s %d\n", d, (int)strlen(d));
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void) {
    char s[] = "AbC";
    for (int i = 0; s[i]; i++) {
        s[i] = (char)tolower((unsigned char)s[i]);
    }
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>
int main(void) {
    int i = 0;
    while (i < 3) {
        printf("%d ", i);
        i++;
    }
    printf("\n");
    return 0;
}
